-- cancelHold: Cancel a hold
-- Changes exactly 1 Hold record of table hold: deletes the record, by id.
-- Dry run: mariadb --init-command="SET @id = '...'" <database> < cancel-hold.sql
-- Apply: the same with @apply = true in the SET. Without it every check runs against the data and the change is rolled back.
SET SESSION sql_mode = CONCAT_WS(',', NULLIF(REPLACE(@@SESSION.sql_mode, 'NO_BACKSLASH_ESCAPES', ''), ''), 'STRICT_ALL_TABLES');
DELIMITER //
BEGIN NOT ATOMIC
  DECLARE found BIGINT;
  DECLARE changed BIGINT;
  DECLARE refusal TEXT;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  -- The variables: each is set, and its text is a value of its column.
  IF @apply IS NOT NULL AND NOT LOWER(@apply) IN ('true', 'false', '1', '0') THEN
    SET refusal = CONCAT('cancel-hold.sql: the variable @apply is ', QUOTE(@apply), ', which is not true or false; nothing was read');
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = refusal;
  END IF;
  IF @id IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'cancel-hold.sql: the variable @id is not set; give it as SET @id = ''<Hold.id>'' (CHAR(36)) in --init-command';
  END IF;
  IF @id IS NOT NULL AND NOT (@id REGEXP '^[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}\\z') THEN
    SET refusal = CONCAT('cancel-hold.sql: the variable @id is ', QUOTE(@id), ', which is not a uuid for Hold.id (CHAR(36)); nothing was read');
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = refusal;
  END IF;
  START TRANSACTION;
  script: BEGIN
    -- 1. Precondition: exactly 1 Hold record to change, locked until the end.
    SELECT COUNT(*) INTO found FROM hold
      WHERE id = CAST(@id AS CHAR)
      FOR UPDATE;
    IF found <> 1 THEN
      SET refusal = CONCAT('operation cancelHold: ', found, ' Hold records hold id ', @id, ', and the change expects exactly 1; nothing was changed');
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = refusal;
    END IF;
    -- 2. The change, under the same condition.
    DELETE FROM hold
      WHERE id = CAST(@id AS CHAR);
    SET changed = ROW_COUNT();
    -- 3. Postcondition: the exact count, and the record holds what was written.
    IF changed <> 1 THEN
      SET refusal = CONCAT('operation cancelHold: the change wrote ', changed, ' Hold records, and exactly 1 was expected; another writer may have changed them after they were counted; nothing was changed');
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = refusal;
    END IF;
    IF EXISTS (SELECT 1 FROM hold WHERE id = CAST(@id AS CHAR)) THEN
      SET refusal = CONCAT('operation cancelHold: after the change the Hold with id ', @id, ' is still there; nothing was changed');
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = refusal;
    END IF;
    -- 4. Dry run unless apply is true.
    IF LOWER(@apply) IN ('true', '1') THEN
      SELECT 'operation cancelHold: 1 Hold record changed; committing' AS message;
      COMMIT;
    ELSE
      SELECT 'operation cancelHold: dry run: 1 Hold record would change, and every check passed; rolling back. Run it again with @apply = true to make the change' AS message;
      ROLLBACK;
    END IF;
  END script;
END//
DELIMITER ;
